dockerStartCmd:
(echo $BASHPID > /rp-watchdog.pid; sleep $(( 1794410408 - $(date +%s) > 1800 ? 1794410408 - $(date +%s) : 1800 )); runpodctl stop pod "$RUNPOD_POD_ID" || runpodctl pod stop "$RUNPOD_POD_ID") > /rp-watchdog.log 2>&1 & setup_guard () 
{ 
    local ws=${RP_GUARD_WS:-/workspace} net=${RP_GUARD_NET:-/proc/net/dev} t=${RP_GUARD_TMP:-/tmp} last seen b state why win;
    function rp_state () 
    { 
        local f n=0 e=0;
        while IFS= read -r f; do
            n=$(( n + 1 ));
            [ ! -s "${f%/run.pid}/run.exit" ] || e=$(( e + 1 ));
        done < <(find "$ws/runs" -mindepth 2 -maxdepth 2 -name run.pid 2> /dev/null);
        if (( n == 0 )); then
            echo none;
        else
            if (( e < n )); then
                echo running;
            else
                echo ended;
            fi;
        fi
    };
    function rp_net () 
    { 
        awk '/:/ { sub(/^ +/, ""); split($0, a, /: */); split(a[2], f, / +/); if (a[1] != "lo") s += f[1] + f[9] } END { printf "%.0f", s }' "$net" 2> /dev/null
    };
    [ ! -e "$ws/.rp-setup-guard" ] || return 0;
    mkdir -p "$ws" && : > "$ws/.rp-setup-guard";
    touch "$t/rp-guard.0";
    last=$(date +%s) seen=$(rp_net);
    while sleep "$2"; do
        state=$(rp_state);
        if [ "$state" = running ]; then
            (( ${5:-0} > 0 )) || return 0;
            last=$(date +%s) seen=$(rp_net);
            continue;
        fi;
        [ "$state" = none ] || (( ${5:-0} > 0 )) || return 0;
        touch "$t/rp-guard.1";
        b=$(rp_net);
        if (( ${b:-0} > ${seen:-0} + 1048576 )) || { 
            [ "$state" = none ] && [ -n "$(timeout 30 find "$ws" -xdev \( -name '*-util.log' -o -name rp-setup-guard.log \) -prune -o -newer "$t/rp-guard.0" -print -quit 2> /dev/null)" ]
        }; then
            last=$(date +%s) seen=$b;
        fi;
        mv -f "$t/rp-guard.1" "$t/rp-guard.0";
        win=$1;
        [ "$state" = none ] || win=$5;
        (( win > 0 && $(date +%s) - last >= win )) || continue;
        [ "$(rp_state)" = "$state" ] || continue;
        why="no command and no input progress";
        [ "$state" = none ] || why="every command ended and no outputs leaving";
        echo "$(date -u '+%F %T') UTC: $why for $win s; runpodctl $3" >> "$ws/rp-setup-guard.log";
        runpodctl $3 "$RUNPOD_POD_ID" || runpodctl $4 "$RUNPOD_POD_ID";
        return 0;
    done
}
setup_guard 900 60 'stop pod' 'pod stop' 1200 > /rp-setup-guard.log 2>&1 < /dev/null & exec /start.sh
